import{cleanTable,exportTable}from'./core.js';
import{t,translateError,languageMenu,bindLanguage}from'./i18n.js';
const check=(id,key,checked=false)=>`<label class="check"><input id="${id}" type="checkbox" ${checked?'checked':''}>${t(key)}</label>`;
document.title=t('title')+' · Paste Table';
document.body.innerHTML=`<header><a class="brand" href="./">P<span>▦</span>T</a><span class="local">● ${t('local')}</span>${languageMenu()}</header><main><section class="intro"><p class="eyebrow">PASTE TABLE / 02</p><h1>${t('headline')}<br><em>${t('accent')}</em></h1><p>${t('intro')}</p></section><section class="workspace"><div class="topline"><h2>01 <span>${t('inputTitle')}</span></h2><button id="example" class="quiet">${t('example')}</button></div><label for="input">${t('inputLabel')}</label><textarea id="input" spellcheck="false"></textarea><div class="labelrow"><label class="file">${t('file')}<input id="file" type="file" accept=".csv,.tsv,.txt,text/csv,text/plain"></label><label class="check">${t('auto')} <select id="delimiter"><option value="auto">${t('auto')}</option><option value="tab">${t('tab')}</option><option value=",">${t('comma')}</option><option value=";">${t('semi')}</option><option value="|">${t('pipe')}</option><option value="spaces">${t('spaces')}</option></select></label></div><p class="hint">${t('limits')}</p><h3>${t('options')}</h3><div class="optiongrid">${check('trim','trimCell',true)}${check('collapse','collapse')}${check('blankRows','blankRows',true)}${check('emptyColumns','emptyColumns')}${check('flatten','flatten')}${check('pad','pad')}</div><div class="actions"><button id="run" class="primary">${t('run')}</button></div><p id="message" role="status" aria-live="polite"></p></section><section id="results" class="workspace" hidden><div class="topline"><h2>02 <span>${t('outputTitle')}</span></h2><span id="size" class="hint"></span></div><div id="stats" class="stats"></div><div class="actions"><label for="format">${t('format')}</label><select id="format"><option value="tsv">TSV</option><option value="csv">CSV</option><option value="markdown">Markdown</option></select><button id="copy" class="secondary">${t('copy')}</button><button id="download" class="secondary">${t('download')}</button></div><div class="actions">${check('safe','safe',true)}${check('header','header',true)}</div><p class="hint">${t('safeNote')}</p><label for="output">${t('outputTitle')}</label><textarea id="output" readonly spellcheck="false"></textarea><p class="hint">${t('previewNote')}</p><h3>${t('preview')}</h3><div class="tablewrap"><table id="preview"></table></div></section><details><summary>${t('rules')}</summary><p id="ruleText"></p><p>${t('standardText')}: <a href="https://www.rfc-editor.org/rfc/rfc4180" target="_blank" rel="noreferrer">RFC 4180</a> · <a href="https://owasp.org/www-community/attacks/CSV_Injection" target="_blank" rel="noreferrer">OWASP CSV Injection</a>.</p></details></main><footer><span>${t('privacy')}</span><a href="https://nanalab.kr/apps/">More Apps ↗</a></footer>`;
bindLanguage();
const $=id=>document.getElementById(id);$('ruleText').textContent=t('ruleText');let result=null;
function message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
function invalidate(){result=null;$('results').hidden=true;$('output').value='';message(t('stale'));}
function output(){if(!result)return;try{$('output').value=exportTable(result.rows,$('format').value,{safe:$('safe').checked,header:$('header').checked,columnName:n=>t('columnName',{n})});$('header').disabled=$('format').value!=='markdown';$('safe').disabled=$('format').value==='markdown';}catch{message(t('formatError'),true);}}
function preview(){const el=$('preview');el.replaceChildren();const body=document.createElement('tbody');for(const [i,row] of result.rows.slice(0,300).entries()){const tr=document.createElement('tr');for(const cell of row){const td=document.createElement(i===0?'th':'td');td.textContent=cell;tr.append(td);}body.append(tr);}el.append(body);}
function run(){try{const options={delimiter:$('delimiter').value==='tab'?'\t':$('delimiter').value};for(const id of ['trim','collapse','blankRows','emptyColumns','flatten','pad'])options[id]=$(id).checked;result=cleanTable($('input').value,options);$('size').textContent=t('count',{rows:result.rows.length,columns:result.rows[0].length});$('stats').replaceChildren();for(const [key,value]of [['changed',result.changed],['removedRows',result.removedRows],['removedColumns',result.removedColumns],['paddedRows',result.paddedRows],['risk',result.riskCount]]){const box=document.createElement('div'),strong=document.createElement('strong'),span=document.createElement('span');box.className='stat'+(key==='risk'&&value?' warn':'');strong.textContent=value;span.textContent=t(key);box.append(strong,span);$('stats').append(box);}output();preview();$('results').hidden=false;message(t('ready'));}catch(e){result=null;$('results').hidden=true;message(e.message==='EMPTY_RESULT'?t('emptyResult'):e.message==='RAGGED'?t('ragged',e):translateError(e),true);}}
$('input').oninput=invalidate;for(const id of ['delimiter','trim','collapse','blankRows','emptyColumns','flatten','pad'])$(id).onchange=invalidate;for(const id of ['format','safe','header'])$(id).onchange=output;$('run').onclick=run;
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);message(t('copied'));}catch{$('output').focus();$('output').select();message(t('copyFail'),true);}};
$('download').onclick=()=>{if(!result)return;const format=$('format').value,mime={csv:'text/csv',tsv:'text/tab-separated-values',markdown:'text/markdown'}[format];const text=(format==='markdown'?'':'\uFEFF')+$('output').value,url=URL.createObjectURL(new Blob([text],{type:mime+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='clean-table.'+(format==='markdown'?'md':format);a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8000000){message(t('fileSize'),true);return;}let input;try{input=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());}catch{message(t('invalidUTF8'),true);return;}$('input').value=input;invalidate();}catch{message(t('fileError'),true);}finally{e.target.value='';}};
$('example').onclick=()=>{$('input').value='코드\t이름\t메모\t\n001\t  샘플 A  \t"첫 줄\n다음 줄"\t\n002\t샘플 B\t"쉼표, 인용 ""확인"""\t\n003\t샘플 C\t=1+2\t\n\t\t\t';$('delimiter').value='auto';$('trim').checked=true;$('collapse').checked=false;$('blankRows').checked=true;$('emptyColumns').checked=false;$('flatten').checked=false;$('pad').checked=false;run();};$('example').click();
